/* Month calendar and quarter-hour agenda for Barber Pro. */
function agendaTime(n){return `${Math.floor(n/60)%12||12}:${String(n%60).padStart(2,'0')} ${n>=720?'PM':'AM'}`;}
function seedBarberCalendar(){if(extras.barberCalendarSeededV2)return;const clients=['Alex Morgan','Ryan Smith','Marcus Reed','Daniel Lee','Chris Parker','Sam Taylor'];for(let offset=0;offset<21;offset++){const date=addDays(today,offset);if(dayBlocked(date,activeBarberId()))continue;const count=offset%3===0?6:offset%3===1?4:2;for(let i=0;i<count;i++){const start=570+i*75;if(conflict(activeBarberId(),date,start,30))continue;const service=servicesFor(activeBarberId()).find(s=>s.id==='cut');if(!service)continue;bookings.push({id:`agenda-example-${date}-${i}`,client:clients[i],barber:activeBarberId(),service:service.id,services:[service.id],bookedServices:[{...service}],durationMin:service.min,estimateCents:Math.round(service.price*100),date,time:agendaTime(start),location:extras.location||'scottsdale',status:'confirmed',policy:structuredClone(extras.bookingPolicy),calendarExample:true});}}extras.barberCalendarSeededV2=true;save();}
function agendaBookings(date){return bookings.filter(b=>b.barber===activeBarberId()&&b.date===date&&b.status!=='cancelled').sort((a,b)=>minutes(a.time)-minutes(b.time));}
function agendaNextFortnight(month,selected){const first=dateObj(month+'-01'),last=new Date(first.getFullYear(),first.getMonth()+1,0).getDate();if(month!==today.slice(0,7)||last-dateObj(today).getDate()>7)return '';first.setMonth(first.getMonth()+1);const next=iso(first).slice(0,7),offset=first.getDay();return `<section class="agenda-next-month"><h3>${pretty(next+'-01',{month:'long'})} · next two weeks</h3><div class="agenda-month-grid">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<span class="agenda-weekday">${d}</span>`).join('')}${'<span></span>'.repeat(offset)}${Array.from({length:14},(_,i)=>{const date=next+'-'+String(i+1).padStart(2,'0'),visits=agendaBookings(date),off=dayBlocked(date,activeBarberId());return `<button class="agenda-day ${date===selected?'selected':''} ${off?'off':''}" data-agenda="day" data-agenda-date="${date}" aria-pressed="${date===selected}" aria-label="${pretty(date)} · ${visits.length} appointments${off?' · Day off':''}"><span>${i+1}</span><span class="agenda-dots">${visits.slice(0,6).map(()=>'<i></i>').join('')}</span>${off?'<small>Off</small>':''}</button>`;}).join('')}</div></section>`;}
const calendarBeforeAgenda=proCalendar;
proCalendar=function(owner=false){if(owner||state.role!=='Barber Pro')return calendarBeforeAgenda(owner);seedBarberCalendar();const selected=state.calendarDate,month=state.agendaMonth||(selected.slice(0,7)===addDays(today,14).slice(0,7)&&dateObj(today).getDate()>21?today.slice(0,7):selected.slice(0,7)),first=dateObj(month+'-01'),start=first.getDay(),last=new Date(first.getFullYear(),first.getMonth()+1,0).getDate(),list=agendaBookings(selected),blocks=extras.blocks.filter(b=>b.barber===activeBarberId()&&b.date===selected);state.agendaDisplayMonth=month;return `${head('Your calendar.','Your chair, at a glance. All times in Arizona.')}<section class="panel agenda-month"><div class="agenda-month-heading"><button class="icon-btn" data-agenda="month" data-direction="-1" aria-label="Previous month">${icon('back')}</button><h2>${pretty(month+'-01',{month:'long',year:'numeric'})}</h2><button class="icon-btn" data-agenda="month" data-direction="1" aria-label="Next month">${icon('chevron')}</button></div><div class="agenda-month-grid">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<span class="agenda-weekday">${d}</span>`).join('')}${'<span></span>'.repeat(start)}${Array.from({length:last},(_,i)=>{const date=month+'-'+String(i+1).padStart(2,'0'),visits=agendaBookings(date),off=dayBlocked(date,activeBarberId());return `<button class="agenda-day ${date===selected?'selected':''} ${off?'off':''} ${date===today?'is-today':''}" data-agenda="day" data-agenda-date="${date}" aria-label="${pretty(date)} · ${visits.length} appointments${off?' · Day off':''}" aria-pressed="${date===selected}"><span>${i+1}</span><span class="agenda-dots">${visits.slice(0,6).map(()=>'<i></i>').join('')}</span>${off?'<small>Off</small>':''}</button>`;}).join('')}</div>${agendaNextFortnight(month,selected)}<p class="agenda-legend"><span>● Appointments</span><span>▧ Blocked day</span><button class="text-btn" data-agenda="today">Today</button></p></section><div class="section-head"><div><h2>${pretty(selected,{weekday:'long',month:'long',day:'numeric'})}</h2><p class="muted">${list.length} appointments · Drag the grip to move a visit</p></div></div><section class="agenda-scroll" aria-label="Daily time agenda"><div class="agenda-track">${Array.from({length:11},(_,i)=>`<div class="agenda-hour" style="top:${i*96}px"><time>${agendaTime((9+i)*60)}</time><span></span></div>`).join('')}${blocks.map(b=>{const from=Math.max(540,clockMinutes(b.start)),to=Math.min(1140,clockMinutes(b.end));return to>from?`<div class="agenda-block" style="top:${(from-540)*1.6}px;height:${(to-from)*1.6}px">${esc(b.reason)} · ${b.start==='00:00'?'All day':agendaTime(from)+' – '+agendaTime(to)}</div>`:'';}).join('')}${list.map(b=>{const locked=!['confirmed','pending_payment'].includes(b.status)||!!checked[b.id]||!!b.ticket?.approval;return `<article class="agenda-visit ${locked?'locked':''}" data-agenda-id="${esc(b.id)}" style="top:${(minutes(b.time)-540)*1.6}px;height:${Math.max(bookingDuration(b)*1.6,48)}px"><button class="agenda-open" data-agenda="visit" data-agenda-id="${esc(b.id)}">${clientPhoto(b.client)}<span><strong class="client-name-row">${customerNameBadges(b.client)}</strong><small class="agenda-live-time">${b.time} – ${agendaTime(minutes(b.time)+bookingDuration(b))}</small><small>${esc(bookingName(b))} · ${cents(b.estimateCents||0)}${locked?' · '+(b.ticket?.approval?'Completed':checked[b.id]?'In the chair':esc(b.status)):''}</small></span></button>${!locked?`<button class="agenda-grip" data-agenda="move" data-agenda-id="${esc(b.id)}" aria-label="Move ${esc(b.client)} appointment" title="Drag or use arrow keys to move">⠿</button>`:''}</article>`;}).join('')}${selected===today?`<div class="agenda-now" style="top:${(Number(new Intl.DateTimeFormat('en-US',{timeZone:'America/Phoenix',hour:'numeric',hourCycle:'h23'}).format(new Date()))*60+Number(new Intl.DateTimeFormat('en-US',{timeZone:'America/Phoenix',minute:'numeric'}).format(new Date()))-540)*1.6}px"><i></i></div>`:''}</div></section><p class="agenda-hint">15-minute steps. Tap a visit for details. Use the grip’s arrow keys as an alternative to dragging.</p>`;};
function agendaValidation(b,date,time){if(!b||state.role!=='Barber Pro'||b.barber!==activeBarberId()||!['confirmed','pending_payment'].includes(b.status)||checked[b.id]||b.ticket?.approval)return 'This visit cannot be moved.';const start=minutes(time),duration=bookingDuration(b);if(!times.includes(time)||start+duration>1140||HFAppRules.appointmentAt({date,time})<=Date.now())return 'Choose a future time within 9 AM–7 PM.';if(bookings.some(x=>x.id!==b.id&&x.barber===b.barber&&x.date===date&&x.status!=='cancelled'&&minutes(x.time)<start+duration&&minutes(x.time)+bookingDuration(x)>start)||extras.blocks.some(x=>x.barber===b.barber&&x.date===date&&clockMinutes(x.start)<start+duration&&clockMinutes(x.end)>start))return 'That time overlaps another visit or blocked time.';return '';}
function confirmAgendaMove(id,start){const b=bookings.find(x=>x.id===id);if(!b)return;const time=agendaTime(start),date=state.calendarDate;if(time===b.time&&date===b.date){render();return;}const dlg=document.createElement('dialog');dlg.className='business-dialog agenda-confirm';dlg.innerHTML=`<h2>Reschedule this visit?</h2><p>${esc(b.client)}</p><p>${pretty(b.date)} · ${b.time}<br>→ <strong>${pretty(date)} · ${time}</strong></p><label class="check-row"><input type="checkbox" name="notify" checked> Notify client in Messages</label><p class="muted">An appointment update will be posted in the client’s conversation. SMS and email are not connected.</p><p class="business-error" role="alert">${agendaValidation(b,date,time)}</p><div class="flex-buttons"><button class="btn" data-agenda-confirm>Confirm reschedule</button><button class="btn secondary" data-agenda-cancel>Keep original</button></div>`;document.body.append(dlg);dlg.showModal();const close=()=>{dlg.close();dlg.remove();render();};dlg.addEventListener('cancel',e=>{e.preventDefault();close();});dlg.addEventListener('click',e=>{if(e.target.closest('[data-agenda-cancel]'))close();if(e.target.closest('[data-agenda-confirm]')){const error=agendaValidation(b,date,time);if(error){dlg.querySelector('[role=alert]').textContent=error;return;}const notify=dlg.querySelector('[name=notify]').checked;b.previousSlots=b.previousSlots||[];b.previousSlots.push({date:b.date,time:b.time,at:Date.now(),by:state.role,notified:notify});b.date=date;b.time=time;if(notify)postAppointment(threadFor(b.client,b.barber),b,'Appointment rescheduled');save();close();toast(notify?'Rescheduled. Client updated in Messages.':'Rescheduled. Client was not notified.');}});}
let agendaDrag=null;
document.addEventListener('pointerdown',e=>{const grip=e.target.closest('.agenda-grip');if(!grip||state.role!=='Barber Pro'||e.button!==0)return;const b=bookings.find(x=>x.id===grip.dataset.agendaId),card=grip.closest('.agenda-visit'),scroll=card.closest('.agenda-scroll');e.preventDefault();grip.setPointerCapture(e.pointerId);agendaDrag={grip,card,scroll,id:b.id,y:e.clientY,scrollTop:scroll.scrollTop,original:minutes(b.time),start:minutes(b.time),duration:bookingDuration(b)};card.classList.add('dragging');});
document.addEventListener('pointermove',e=>{const d=agendaDrag;if(!d)return;e.preventDefault();const rect=d.scroll.getBoundingClientRect();if(e.clientY<rect.top+45)d.scroll.scrollTop-=12;if(e.clientY>rect.bottom-45)d.scroll.scrollTop+=12;d.start=Math.max(540,Math.min(Math.floor((1140-d.duration)/15)*15,Math.round((d.original+(e.clientY-d.y+d.scroll.scrollTop-d.scrollTop)/1.6)/15)*15));d.card.style.top=(d.start-540)*1.6+'px';d.card.querySelector('.agenda-live-time').textContent=agendaTime(d.start)+' – '+agendaTime(d.start+d.duration);d.card.classList.toggle('invalid',!!agendaValidation(bookings.find(b=>b.id===d.id),state.calendarDate,agendaTime(d.start)));},{passive:false});
document.addEventListener('pointerup',()=>{const d=agendaDrag;if(!d)return;agendaDrag=null;d.card.classList.remove('dragging');confirmAgendaMove(d.id,d.start);});
document.addEventListener('pointercancel',()=>{if(agendaDrag){agendaDrag=null;render();}});
document.addEventListener('keydown',e=>{const grip=e.target.closest('.agenda-grip');if(!grip||!['ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const b=bookings.find(b=>b.id===grip.dataset.agendaId);confirmAgendaMove(b.id,minutes(b.time)+(e.key==='ArrowDown'?15:-15));});
// Handle navigation before legacy appointment handlers can interpret stale visit state.
document.addEventListener('click',e=>{if(state.role!=='Barber Pro')return;const nav=e.target.closest('button[data-view=pCalendar]');if(nav){e.preventDefault();e.stopImmediatePropagation();go('pCalendar');return;}const el=e.target.closest('[data-agenda]');if(!el)return;e.preventDefault();e.stopImmediatePropagation();const d=el.dataset;if(d.agenda==='month'){const date=dateObj((state.agendaMonth||state.agendaDisplayMonth||state.calendarDate.slice(0,7))+'-01');date.setMonth(date.getMonth()+Number(d.direction));state.agendaMonth=iso(date).slice(0,7);render();}if(d.agenda==='day'){state.calendarDate=d.agendaDate;render();}if(d.agenda==='today'){state.calendarDate=today;state.agendaMonth=today.slice(0,7);render();}if(d.agenda==='visit'){rememberAppointmentOrigin();openAppointment(d.agendaId);}},true);
render();
